const d = $json;
const dialogos = d.dialogos || [];
const etapas = d.etapas || [];
const sys = 'Sos un analista senior de Business Intelligence para agentes de ventas conversacionales de universidades. Analizás diálogos reales entre leads y el bot para extraer inteligencia de negocio accionable. Sé concreto: citá ejemplos textuales de los diálogos. Respondé SOLO JSON válido con esta forma exacta: {"resumen":"3-4 oraciones ejecutivas sobre qué buscan los leads y cómo responde el bot","temas_frecuentes":[{"tema":"...","frecuencia":"alta|media|baja","ejemplo":"cita textual"}],"objeciones":[{"objecion":"...","ejemplo":"cita textual","sugerencia":"cómo manejarla mejor"}],"huecos_kb":[{"pregunta":"pregunta que el bot NO pudo responder bien o derivó sin necesidad","motivo":"..."}],"recomendaciones":["accion concreta para mejorar conversion o precision"]}. Max 6 temas, 5 objeciones, 6 huecos, 5 recomendaciones.';
const usr = 'ETAPAS DEL AGENTE:
' + etapas.map(e=>'- '+e.nombre+': '+(e.objetivo||'')).join('
')
  + '

DIALOGOS RECIENTES (lead -> bot), del mas nuevo al mas viejo:
'
  + dialogos.map(x=>'[' + (x.etapa_nombre||'?') + '] LEAD: ' + (x.p||'') + '
BOT: ' + String(x.r||'').slice(0,300)).join('
---
');
return [{ json: { payload: { model: 'o4-mini', response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: usr.slice(0, 180000) } ] } } }];

let out = {};
try { out = JSON.parse($json.choices[0].message.content); } catch (e) { out = { error: 'parse', raw: String($json.choices?.[0]?.message?.content||'').slice(0,500) }; }
out.generado_en = new Date().toISOString();
out.dialogos_analizados = $('Juntar datos').first().json.dialogos ? $('Juntar datos').first().json.dialogos.length : 0;
return [{ json: out }];
